package com.kuaixietech.coupler;
import com.kuaixietech.integration.IntegrationCipher;
import com.kuaixietech.security.DomainAccessGuard;
import java.util.*;
import org.springframework.http.HttpStatus;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;
import static com.kuaixietech.coupler.CouplerModels.*;
import com.kuaixietech.coupler.CouplerModels.Runtime;
@Service
public class CouplerService {
 private final JdbcTemplate db;private final DomainAccessGuard guard;private final IntegrationCipher cipher;private final CouplerCatalog catalog;private final CouplerAdapterRegistry adapters;private final java.util.function.Function<String,String> environment;
 @org.springframework.beans.factory.annotation.Autowired public CouplerService(JdbcTemplate db,DomainAccessGuard guard,IntegrationCipher cipher,CouplerCatalog catalog,CouplerAdapterRegistry adapters){this(db,guard,cipher,catalog,adapters,System::getenv);}
 CouplerService(JdbcTemplate db,DomainAccessGuard guard,IntegrationCipher cipher,CouplerCatalog catalog,CouplerAdapterRegistry adapters,java.util.function.Function<String,String> environment){this.db=db;this.guard=guard;this.cipher=cipher;this.catalog=catalog;this.adapters=adapters;this.environment=environment;}
 private Map<String,Object> row(String sql,Object...args){return db.queryForList(sql,args).stream().findFirst().orElse(null);}
 private long number(Object value){return value==null?0:((Number)value).longValue();}
 private boolean truth(Object value){return Boolean.TRUE.equals(value)||"1".equals(String.valueOf(value));}
 private ResponseStatusException reject(String code){return new ResponseStatusException(HttpStatus.CONFLICT,code);}
 private void changed(int count){if(count!=1)throw new IllegalStateException("COUPLER_CONCURRENT_CHANGE");}
 public Runtime current(){var row=row("SELECT current_mode,revision FROM t_integration_runtime_state WHERE id=1");return row==null?new Runtime(Mode.SANDBOX,0):new Runtime(Mode.valueOf(row.get("current_mode").toString()),number(row.get("revision")));}
 private Map<String,Object> scope(Mode mode,String category){return row("SELECT selected_provider,revision,updated_at FROM t_integration_mode_scopes WHERE mode=? AND category=?",mode.name(),category);}
 private Map<String,Object> config(Mode mode,String category,String provider){return row("SELECT enabled,config_revision,updated_at FROM t_integration_mode_configs WHERE mode=? AND category=? AND provider=?",mode.name(),category,provider);}
 private static String aad(Mode mode,String category,String provider,long revision,String field){return "coupler/"+mode.name()+"/"+category+"/"+provider+"/"+revision+"/"+field;}
 private record Values(Map<String,String> plain,List<String> unreadable,Set<String> configured){}
 private Values values(Mode mode,Provider provider,long revision){return decodedValues(mode,provider,revision,revision<1?List.of():db.queryForList("SELECT field_key,field_cipher FROM t_integration_config_values WHERE mode=? AND category=? AND provider=? AND config_revision=?",mode.name(),provider.category(),provider.code(),revision));}
 private Values decodedValues(Mode mode,Provider provider,long revision,List<Map<String,Object>> rows){var plain=new LinkedHashMap<String,String>();var unreadable=new ArrayList<String>();var configured=new LinkedHashSet<String>();if(revision<1)return new Values(plain,unreadable,configured);Set<String> known=new HashSet<>();provider.fields().forEach(f->known.add(f.key()));for(var field:rows){String key=Objects.toString(field.get("field_key"),"");if(!known.contains(key))throw new IllegalStateException("COUPLER_STORED_FIELD_UNKNOWN");configured.add(key);try{plain.put(key,cipher.open(aad(mode,provider.category(),provider.code(),revision,key),field.get("field_cipher").toString()));}catch(IllegalStateException e){unreadable.add(key);}}return new Values(plain,List.copyOf(unreadable),Set.copyOf(configured));}
 /** Resolve references only during an explicit administrator save, then encrypt the resolved value as that immutable revision. */
 private Map<String,String> snapshotAtSave(Map<String,String> plain){var result=new LinkedHashMap<String,String>();for(var entry:plain.entrySet()){String value=entry.getValue();if(value.startsWith("env:")){String name=value.substring(4);if(!name.matches("[A-Z][A-Z0-9_]{2,99}"))throw new IllegalStateException("COUPLER_ENV_REFERENCE_INVALID");value=environment.apply(name);if(value==null||value.isBlank())throw new IllegalStateException("COUPLER_ENV_REFERENCE_MISSING");if(value.startsWith("env:"))throw new IllegalStateException("COUPLER_ENV_REFERENCE_NESTED");}result.put(entry.getKey(),value);}return Map.copyOf(result);}
 /** Old unresolved references cannot be rebound to today's environment for either new execution or historical queries. */
 private Map<String,String> effective(Map<String,String> plain){for(String value:plain.values())if(value.startsWith("env:"))throw new IllegalStateException("COUPLER_UNVERSIONED_ENV_REFERENCE_RESAVE_REQUIRED");return Map.copyOf(plain);}

 private Map<String,Object> metadata(Mode mode,Provider p,Map<String,Object> s,Map<String,Object> c,List<Map<String,Object>> rows){long revision=c==null?0:number(c.get("config_revision"));var values=decodedValues(mode,p,revision,rows);var visible=new LinkedHashMap<String,String>();for(var field:p.fields())if(!field.secret()&&values.plain().containsKey(field.key()))visible.put(field.key(),values.plain().get(field.key()));return Map.of("revision",s==null?0:number(s.get("revision")),"configRevision",revision,"enabled",c!=null&&truth(c.get("enabled")),"selected",s!=null&&p.code().equals(s.get("selected_provider")),"values",visible,"configuredFields",values.configured(),"unreadableFields",values.unreadable(),"updatedAt",c==null?"":Objects.toString(c.get("updated_at"),""));}
 @Transactional(readOnly=true,isolation=org.springframework.transaction.annotation.Isolation.REPEATABLE_READ) public Map<String,Object> settings(){guard.requireAdmin();var allScopes=new HashMap<String,Map<String,Object>>();for(var row:db.queryForList("SELECT mode,category,selected_provider,revision,updated_at FROM t_integration_mode_scopes"))allScopes.put(row.get("mode")+"/"+row.get("category"),row);var allConfigs=new HashMap<String,Map<String,Object>>();for(var row:db.queryForList("SELECT mode,category,provider,enabled,config_revision,updated_at FROM t_integration_mode_configs"))allConfigs.put(row.get("mode")+"/"+row.get("category")+"/"+row.get("provider"),row);var allValues=new HashMap<String,List<Map<String,Object>>>();for(var row:db.queryForList("SELECT v.mode,v.category,v.provider,v.config_revision,v.field_key,v.field_cipher FROM t_integration_config_values v JOIN t_integration_mode_configs c ON c.mode=v.mode AND c.category=v.category AND c.provider=v.provider AND c.config_revision=v.config_revision"))allValues.computeIfAbsent(row.get("mode")+"/"+row.get("category")+"/"+row.get("provider"),key->new ArrayList<>()).add(row);var categories=new ArrayList<Map<String,Object>>();for(var category:catalog.all()){var providers=new ArrayList<Map<String,Object>>();for(var p:category.providers()){var data=new LinkedHashMap<String,Object>();data.put("vendor",p.vendor());data.put("product",p.product());data.put("code",p.code());data.put("name",p.name());data.put("capability",p.capability());data.put("docs",p.docs());data.put("sdkAvailable",p.sdkAvailable());data.put("businessVerified",false);data.put("consumerWired",p.consumerWired());data.put("supportedModes",p.supportedModes());data.put("implementedOperations",p.implementedOperations());data.put("fields",p.fields());var modes=new LinkedHashMap<String,Object>();for(var mode:Mode.values()){String key=mode.name()+"/"+category.code()+"/"+p.code();modes.put(mode.name(),metadata(mode,p,allScopes.get(mode.name()+"/"+category.code()),allConfigs.get(key),allValues.getOrDefault(key,List.of())));}data.put("configurationByMode",modes);providers.add(data);}categories.add(Map.of("code",category.code(),"name",category.name(),"description",category.description(),"providers",providers));}return Map.of("runtime",current(),"categories",categories,"encryptionReady",cipher.ready());}
 @Transactional public Runtime switchMode(Switch input){String actor=guard.requireAdmin();db.update("INSERT IGNORE INTO t_integration_runtime_state(id,current_mode,revision) VALUES(1,'SANDBOX',0)");var stored=row("SELECT current_mode,revision FROM t_integration_runtime_state WHERE id=1 FOR UPDATE");long revision=number(stored.get("revision"));if(revision!=input.expectedRevision())throw reject("COUPLER_RUNTIME_CHANGED_REFRESH");changed(db.update("UPDATE t_integration_runtime_state SET current_mode=?,revision=revision+1,updated_by=? WHERE id=1 AND revision=?",input.mode().name(),actor,revision));audit(actor,"coupler_runtime",input.mode().name(),"API routing mode changed; existing live records retain their original environment");return new Runtime(input.mode(),revision+1);}
 @Transactional public Map<String,Long> save(String category,String provider,Mode mode,Save input){String actor=guard.requireAdmin();Provider p=catalog.provider(category,provider);if(input.selected()&&!p.consumerWired())throw new IllegalArgumentException("COUPLER_BUSINESS_CONSUMER_UNAVAILABLE");if(!cipher.ready())throw new IllegalStateException("COUPLER_ENCRYPTION_KEY_REQUIRED");Map<String,Field> known=new LinkedHashMap<>();p.fields().forEach(f->known.put(f.key(),f));for(String key:input.values().keySet())if(!known.containsKey(key)||key.startsWith("_"))throw new IllegalArgumentException("COUPLER_UNKNOWN_FIELD");for(String key:input.clearFields())if(!known.containsKey(key)||key.startsWith("_")||input.values().containsKey(key))throw new IllegalArgumentException("COUPLER_UNKNOWN_FIELD");
  db.update("INSERT IGNORE INTO t_integration_mode_scopes(mode,category,revision) VALUES(?,?,0)",mode.name(),category);var scope=row("SELECT selected_provider,revision FROM t_integration_mode_scopes WHERE mode=? AND category=? FOR UPDATE",mode.name(),category);long expected=number(scope.get("revision"));if(expected!=input.expectedRevision())throw reject("COUPLER_SCOPE_CHANGED_REFRESH");db.update("INSERT IGNORE INTO t_integration_mode_configs(mode,category,provider,enabled,config_revision) VALUES(?,?,?,0,0)",mode.name(),category,provider);var current=row("SELECT enabled,config_revision FROM t_integration_mode_configs WHERE mode=? AND category=? AND provider=? FOR UPDATE",mode.name(),category,provider);long priorRevision=number(current.get("config_revision")),nextRevision=priorRevision+1;var previous=values(mode,p,priorRevision);var merged=new LinkedHashMap<>(previous.plain());for(String key:input.clearFields())merged.remove(key);merged.putAll(input.values());List<String> unresolved=previous.unreadable().stream().filter(key->!input.values().containsKey(key)&&!input.clearFields().contains(key)).toList();
  merged=new LinkedHashMap<>(snapshotAtSave(merged));
  if(input.enabled()){if(!unresolved.isEmpty())throw reject("COUPLER_CREDENTIAL_UNREADABLE");validateRequired(p,merged);adapters.validate(p,mode,nextRevision,effective(merged));}
  for(var value:merged.entrySet())changed(db.update("INSERT INTO t_integration_config_values(mode,category,provider,config_revision,field_key,field_cipher) VALUES(?,?,?,?,?,?)",mode.name(),category,provider,nextRevision,value.getKey(),cipher.seal(aad(mode,category,provider,nextRevision,value.getKey()),value.getValue())));
  changed(db.update("UPDATE t_integration_mode_configs SET enabled=?,config_revision=?,updated_by=? WHERE mode=? AND category=? AND provider=? AND config_revision=?",input.enabled(),nextRevision,actor,mode.name(),category,provider,priorRevision));String selected=input.selected()?provider:Objects.equals(scope.get("selected_provider"),provider)?null:Objects.toString(scope.get("selected_provider"),null);changed(db.update("UPDATE t_integration_mode_scopes SET selected_provider=?,revision=revision+1,updated_by=? WHERE mode=? AND category=? AND revision=?",selected,actor,mode.name(),category,expected));audit(actor,"coupler_provider",category+"/"+provider,"Environment "+mode.name()+" revision "+nextRevision+" saved; credential values excluded");return Map.of("revision",expected+1,"configRevision",nextRevision);
 }
 private void validateRequired(Provider p,Map<String,String> fields){for(var field:p.fields())if(field.required()&&fields.getOrDefault(field.key(),"").isBlank())throw new IllegalArgumentException("COUPLER_REQUIRED_FIELD_MISSING");}
 public Map<String,Object> validate(String category,String provider,Mode mode){guard.requireAdmin();var p=catalog.provider(category,provider);var s=scope(mode,category);var c=config(mode,category,provider);long version=c==null?0:number(c.get("config_revision"));var values=values(mode,p,version);var missing=new ArrayList<String>();for(var field:p.fields())if(field.required()&&!values.configured().contains(field.key())||field.required()&&values.plain().getOrDefault(field.key(),"").isBlank()&&!values.unreadable().contains(field.key()))missing.add(field.key());var invalid=new ArrayList<String>();if(!p.supportedModes().contains(mode))invalid.add("mode");if(missing.isEmpty()&&values.unreadable().isEmpty()&&invalid.isEmpty())try{adapters.validate(p,mode,Math.max(1,version),effective(values.plain()));}catch(RuntimeException e){invalid.add("configuration");}return Map.of("mode",mode,"revision",s==null?0:number(s.get("revision")),"ready",missing.isEmpty()&&invalid.isEmpty()&&values.unreadable().isEmpty()&&version>0,"missingFields",missing,"invalidFields",invalid,"unreadableFields",values.unreadable(),"sdkAvailable",p.sdkAvailable(),"businessVerified",false,"checks",List.of(Map.of("code","LOCAL_ONLY","status","info","message","Local configuration/SDK checks only; no provider request or live business verification")));}
 /** New business operation resolution. One immutable scope/version, no current-mode rereads after return. */
 @Transactional(readOnly=true,isolation=org.springframework.transaction.annotation.Isolation.REPEATABLE_READ) public Resolved resolve(String category){Mode mode=current().mode();return resolveForMode(category,mode,true);}
 private Resolved resolveForMode(String category,Mode mode,boolean featureCheck){catalog.category(category);var s=scope(mode,category);if(s==null||s.get("selected_provider")==null)throw new IllegalStateException("COUPLER_PROVIDER_NOT_SELECTED");String selected=s.get("selected_provider").toString();var p=catalog.provider(category,selected);var c=config(mode,category,selected);if(c==null||!truth(c.get("enabled")))throw new IllegalStateException("COUPLER_PROVIDER_DISABLED");long revision=number(c.get("config_revision"));var values=values(mode,p,revision);if(!values.unreadable().isEmpty())throw new IllegalStateException("COUPLER_CREDENTIAL_UNREADABLE");var effective=effective(values.plain());validateRequired(p,effective);adapters.validate(p,mode,revision,effective);if(featureCheck&&!category.equals("FEATURES")){var flags=resolveForMode("FEATURES",mode,false);if(!"true".equals(flags.values().get(category.toLowerCase(Locale.ROOT)+"_enabled")))throw new IllegalStateException("COUPLER_FEATURE_DISABLED");}var snapshot=new LinkedHashMap<>(effective);snapshot.put("_runtime_mode",mode.name());snapshot.put("_coupler_config_revision",Long.toString(revision));return new Resolved(mode,category,selected,revision,number(s.get("revision")),snapshot);}
 private record Mapping(String category,String provider){}
 private Mapping mapping(String vendor,String product){return switch(vendor+"/"+product){case "aliyun/sms"->new Mapping("SMS","aliyun");case "tencent/sms"->new Mapping("SMS","tencent");case "aliyun/oss"->new Mapping("OSS","aliyun");case "tencent/cos"->new Mapping("OSS","tencent");case "wechat/miniprogram"->new Mapping("MINIAPP","weixin");case "aliyun/directmail"->new Mapping("EMAIL","aliyun");default->null;};}
 public void requireLegacyFeature(String category){Mode mode=current().mode();var flags=scope(mode,"FEATURES");if(flags!=null){var resolved=resolveForMode("FEATURES",mode,false);if(!"true".equals(resolved.values().get(category.toLowerCase(Locale.ROOT)+"_enabled")))throw new IllegalStateException("COUPLER_FEATURE_DISABLED");}}
 public boolean managed(String vendor,String product){var map=mapping(vendor,product);return map!=null&&scope(current().mode(),map.category())!=null;}
 @Transactional(readOnly=true,isolation=org.springframework.transaction.annotation.Isolation.REPEATABLE_READ) public LegacyRoute legacyNewCall(String vendor,String product){var map=mapping(vendor,product);Mode mode=current().mode();if(map==null)return new LegacyRoute(mode!=Mode.LIVE,null);var s=scope(mode,map.category());if(s==null){if(mode==Mode.LIVE)requireLegacyFeature(map.category());return new LegacyRoute(mode!=Mode.LIVE,null);}if(!map.provider().equals(s.get("selected_provider")))return new LegacyRoute(true,null);var c=config(mode,map.category(),map.provider());if(c==null||!truth(c.get("enabled")))return new LegacyRoute(true,null);if(mode!=Mode.LIVE)return new LegacyRoute(true,null);return new LegacyRoute(true,resolveForMode(map.category(),mode,true).values());}
 /** Existing objects retain their original LIVE provider; global mode and a newly selected vendor are irrelevant. */
 @Transactional(readOnly=true,isolation=org.springframework.transaction.annotation.Isolation.REPEATABLE_READ) public LegacyRoute historicalLive(String vendor,String product,long requestedRevision){var map=mapping(vendor,product);if(map==null){if(requestedRevision>0)throw new IllegalStateException("COUPLER_HISTORICAL_BINDING_UNKNOWN");return new LegacyRoute(false,null);}var c=config(Mode.LIVE,map.category(),map.provider());if(c==null){if(requestedRevision>0)throw new IllegalStateException("COUPLER_HISTORICAL_REVISION_MISSING");return new LegacyRoute(false,null);}long revision=requestedRevision>0?requestedRevision:number(c.get("config_revision"));var values=values(Mode.LIVE,catalog.provider(map.category(),map.provider()),revision);if(!values.unreadable().isEmpty()||values.configured().isEmpty())throw new IllegalStateException("COUPLER_HISTORICAL_CREDENTIAL_UNAVAILABLE");var snapshot=new LinkedHashMap<>(effective(values.plain()));snapshot.put("_runtime_mode","LIVE");snapshot.put("_coupler_config_revision",Long.toString(revision));return new LegacyRoute(true,Map.copyOf(snapshot));}
 private void audit(String actor,String action,String target,String detail){changed(db.update("INSERT INTO t_admin_logs(id,operator_id,action,target_type,target_id,detail) VALUES(?,?,?,'integration',?,?)",UUID.randomUUID().toString(),actor,action,target,detail));}
}
